def test_duplicate_keeps_later_row_in_file_order() -> None:
    rows = [
        RawRow(date="2025-03-03", ticker="AAA", close=1.0),
        RawRow(date="2025-03-03", ticker="BBB", close=5.0),
        RawRow(date="2025-03-03", ticker="AAA", close=2.0),
    ]
    assert validate_rows(rows) == [
        RawRow(date="2025-03-03", ticker="AAA", close=2.0),
        RawRow(date="2025-03-03", ticker="BBB", close=5.0),
    ]


def test_unusable_later_duplicate_does_not_replace_usable_one() -> None:
    rows = [
        RawRow(date="2025-03-03", ticker="AAA", close=1.0),
        RawRow(date="2025-03-03", ticker="AAA", close=None),
    ]
    assert validate_rows(rows) == [RawRow(date="2025-03-03", ticker="AAA", close=1.0)]


